UPDATE untersuchungsehen
SET strabismusAuftreten = NULL
WHERE strabismusAuftreten = '';

UPDATE untersuchungsehen
SET strabismusAuftreten = split_part(strabismusAuftreten, ',', 1)
WHERE strabismusAuftreten IS NOT NULL;

UPDATE untersuchungsehen
SET strabismusAuspraegung = NULL
WHERE strabismusAuspraegung = '';

UPDATE untersuchungsehen
SET strabismusAuspraegung = split_part(strabismusAuspraegung, ',', 1)
WHERE strabismusAuspraegung IS NOT NULL;

